CREATE MULTISET TABLE MDP01_META.META_VIEW_LINEAGE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      VIEW_TABLE_ID INTEGER NOT NULL,      SOURCE_TABLE_ID INTEGER,      SOURCE_DB VARCHAR(128) CHARACTER SET UNICODE NOT CASESPECIFIC,      SOURCE_NAME VARCHAR(128) CHARACTER SET UNICODE NOT CASESPECIFIC,      REQUEST_TEXT_HASH VARCHAR(64) CHARACTER SET UNICODE NOT CASESPECIFIC,      PARSED_AT TIMESTAMP(0))PRIMARY INDEX ( VIEW_TABLE_ID );